AIRRIDE_HTML = r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>NAP Air Ride</title><style>
body{background:#09151c;color:#eef5f6;font:18px system-ui;margin:0}main{max-width:760px;margin:auto;padding:24px}a{color:#78d7e2}h1{margin-bottom:8px}.sub{color:#a8bdc4}#status{padding:16px;background:#18323d;border-radius:12px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}button{font:700 22px system-ui;border:1px solid #51737c;background:#17303a;color:white;border-radius:16px;min-height:110px;padding:20px;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}button:disabled{opacity:.35}button.held{background:#875a17;box-shadow:0 0 0 3px #edb951}#stop{width:100%;margin:16px 0;background:#6a2729}.wide{grid-column:span 2}details{margin-top:24px}summary{padding:12px;cursor:pointer}.corners button{min-height:90px;font-size:18px}footer{margin-top:24px;font-size:15px;color:#a8bdc4}</style></head><body><main><a href="/">← NAP dashboard</a><h1>Air Ride Control</h1><div class="sub">Hold to lower. Let go to stop venting and restore factory leveling.</div><div id="status" role="status" aria-live="polite">Checking controller…</div><div class="grid"><button data-group="front" disabled>Front Down</button><button data-group="rear" disabled>Rear Down</button><button class="wide" data-group="pancake" disabled>Pancake · All Four</button></div><button id="stop">Restore Factory Control</button><button id="reset" disabled style="width:100%;min-height:60px;font-size:18px">Reset Error</button><details><summary>Individual corners</summary><div class="grid corners"><button data-group="fl" disabled>Driver Front</button><button data-group="fr" disabled>Passenger Front</button><button data-group="rl" disabled>Driver Rear</button><button data-group="rr" disabled>Passenger Rear</button></div></details><footer>Manual controls lock at 40 mph and whenever speed data is unavailable. Corners pulse in sequence every 0.8 seconds. Letting go stops venting and runs the factory restore routine. Restore Factory Control runs the recovered restore sequence. Reset Error clears a completed fault without moving the suspension; press a hold button again to retry. Restoring control does not command a specific height.</footer></main><script>
const buttons=[...document.querySelectorAll('[data-group]')],status=document.getElementById('status');let hold=null,timer=null,available=false,lastStatus=0,releasePending=false;
async function command(d){const r=await fetch('/api/airride',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const s=await r.json();if(!r.ok||s.error)throw Error(s.error||'Command failed');return s}
function render(s){lastStatus=Date.now();available=!!s.available;document.getElementById('reset').disabled=!s.reset_available;buttons.forEach(b=>b.disabled=!available||releasePending);status.textContent=(s.speed_mph==null?'Speed unavailable':s.speed_mph.toFixed(1)+' mph')+' · '+(s.error||s.fault||s.reason||'Controller unavailable');if(!available&&hold)stop()}
function stop(all=false){const old=hold;hold=null;clearTimeout(timer);buttons.forEach(b=>b.classList.remove('held'));if((old||all)&&!releasePending){releasePending=true;buttons.forEach(b=>b.disabled=true);command({action:'restore'}).then(render).catch(e=>{status.textContent='Factory restoration unconfirmed: '+e.message}).finally(()=>{releasePending=false})}}
async function heartbeat(h){if(hold!==h)return;try{render(await command({action:'heartbeat',token:h.token,group:h.group}));if(hold===h)timer=setTimeout(()=>heartbeat(h),200)}catch(e){stop();status.textContent=e.message}}
buttons.forEach(b=>{b.addEventListener('pointerdown',async e=>{if(e.button!==0||!available||releasePending||hold)return;e.preventDefault();window.getSelection()?.removeAllRanges();const h={token:crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join(''),group:b.dataset.group};hold=h;b.classList.add('held');b.setPointerCapture(e.pointerId);try{render(await command({action:'start',...h}));if(hold===h)timer=setTimeout(()=>heartbeat(h),200)}catch(err){stop();status.textContent=err.message}});['pointerup','pointercancel','lostpointercapture','pointerleave'].forEach(event=>b.addEventListener(event,()=>stop()));b.addEventListener('touchstart',e=>e.preventDefault(),{passive:false});b.addEventListener('selectstart',e=>e.preventDefault());b.addEventListener('dragstart',e=>e.preventDefault());b.addEventListener('contextmenu',e=>e.preventDefault())});
document.addEventListener('selectstart',e=>{if(hold||e.target.closest?.('button'))e.preventDefault()});window.addEventListener('touchend',()=>stop(),true);window.addEventListener('touchcancel',()=>stop(),true);window.addEventListener('pointerup',()=>stop(),true);window.addEventListener('pointercancel',()=>stop(),true);
document.getElementById('stop').onclick=()=>stop(true);document.getElementById('reset').onclick=async()=>{document.getElementById('reset').disabled=true;try{render(await command({action:'reset'}))}catch(e){status.textContent=e.message}};window.addEventListener('blur',()=>stop());document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',()=>{if(hold)fetch('/api/airride',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'restore'}),keepalive:true});hold=null});
async function poll(){try{const r=await fetch('/api/airride/status',{cache:'no-store'});render(await r.json())}catch(e){available=false;document.getElementById('reset').disabled=true;buttons.forEach(b=>b.disabled=true);stop();status.textContent='Controller connection lost'}setTimeout(poll,250)}setInterval(()=>{if(Date.now()-lastStatus>1000){available=false;buttons.forEach(b=>b.disabled=true);stop()}},200);poll();
</script></body></html>'''
